({
  init(msg) {
    this.data = this.data || { services: {} };
    if (!this.data.services) {
      this.data.services = {};
    }
    this._checkInvariants();
    return { ok: true };
  },

  recordPing(msg) {
    const payload = msg?.payload;
    this.ensure(payload && typeof payload === 'object', "Payload must be an object");
    this.ensure(typeof payload.serviceId === 'string' && payload.serviceId.trim().length > 0, "serviceId must be a non-empty string");
    this.ensure(typeof payload.ok === 'boolean', "ok must be a boolean");
    this.ensure(typeof payload.latencyMs === 'number' && !isNaN(payload.latencyMs) && payload.latencyMs >= 0, "latencyMs must be a non-negative number");

    this._ensureData();

    const serviceId = payload.serviceId.trim();
    if (!this.data.services[serviceId]) {
      this.data.services[serviceId] = { pings: [] };
    }

    const serviceRecord = this.data.services[serviceId];
    const prevCount = serviceRecord.pings.length;

    serviceRecord.pings.push({
      ok: payload.ok,
      latencyMs: payload.latencyMs,
      timestamp: Date.now()
    });

    this._checkInvariants();
    this.changed("pingRecorded", { serviceId, ok: payload.ok, latencyMs: payload.latencyMs });

    const result = {
      recorded: true,
      serviceId,
      totalPings: serviceRecord.pings.length
    };

    this.ensure(result.totalPings === prevCount + 1, "Ping count must increment by 1");
    return result;
  },

  getReport(msg) {
    const payload = msg?.payload;
    this.ensure(payload && typeof payload === 'object', "Payload must be an object");
    this.ensure(typeof payload.serviceId === 'string' && payload.serviceId.trim().length > 0, "serviceId must be a non-empty string");

    this._ensureData();

    const serviceId = payload.serviceId.trim();
    const serviceRecord = this.data.services[serviceId];
    const pings = serviceRecord ? serviceRecord.pings : [];
    const totalPings = pings.length;

    let uptimePercentage = 0;
    let p95LatencyMs = 0;
    let successfulPings = 0;

    if (totalPings > 0) {
      successfulPings = pings.filter(p => p.ok).length;
      uptimePercentage = (successfulPings / totalPings) * 100;

      const sortedLatencies = pings.map(p => p.latencyMs).sort((a, b) => a - b);
      const p95Index = Math.min(sortedLatencies.length - 1, Math.max(0, Math.ceil(sortedLatencies.length * 0.95) - 1));
      p95LatencyMs = sortedLatencies[p95Index];
    }

    const report = {
      serviceId,
      totalPings,
      successfulPings,
      uptimePercentage,
      p95LatencyMs
    };

    this.ensure(typeof report.uptimePercentage === 'number' && report.uptimePercentage >= 0 && report.uptimePercentage <= 100, "Uptime percentage must be between 0 and 100");
    this.ensure(typeof report.p95LatencyMs === 'number' && report.p95LatencyMs >= 0, "p95 latency must be a non-negative number");

    return report;
  },

  resetHistory(msg) {
    const payload = msg?.payload;
    this.ensure(payload && typeof payload === 'object', "Payload must be an object");
    this.ensure(typeof payload.serviceId === 'string' && payload.serviceId.trim().length > 0, "serviceId must be a non-empty string");

    this._ensureData();

    const serviceId = payload.serviceId.trim();
    if (this.data.services[serviceId]) {
      this.data.services[serviceId] = { pings: [] };
    }

    this._checkInvariants();
    this.changed("historyReset", { serviceId });

    const result = {
      reset: true,
      serviceId
    };

    const remainingPings = this.data.services[serviceId] ? this.data.services[serviceId].pings.length : 0;
    this.ensure(remainingPings === 0, "Service ping history must be empty after reset");

    return result;
  },

  _ensureData() {
    if (!this.data || typeof this.data !== 'object') {
      this.data = { services: {} };
    }
    if (!this.data.services || typeof this.data.services !== 'object') {
      this.data.services = {};
    }
  },

  _checkInvariants() {
    this.invariant(this.data && typeof this.data === 'object', "this.data must be an object");
    this.invariant(this.data.services && typeof this.data.services === 'object', "this.data.services must be an object");

    for (const [id, service] of Object.entries(this.data.services)) {
      this.invariant(typeof id === 'string', "Service ID key must be a string");
      this.invariant(service && Array.isArray(service.pings), `Service entry for ${id} must contain a pings array`);
      for (const ping of service.pings) {
        this.invariant(typeof ping.ok === 'boolean', "Ping 'ok' flag must be a boolean");
        this.invariant(typeof ping.latencyMs === 'number' && !isNaN(ping.latencyMs) && ping.latencyMs >= 0, "Ping 'latencyMs' must be a non-negative number");
      }
    }
  }
})
